#ifndef LISTA_H
#define LISTA_H

#define MAX 10

typedef enum {
  OK,
  LISTA_LLENA,
  POSICION_INVALIDA
} TResultado;

typedef struct {
  int elementos[MAX];
  int cantidad;
} TLista;

void inicializar(TLista *l);
int longitud(TLista l);
int obtener(TLista l, int pos);
TResultado insertar(TLista *l, int pos, int x);

#endif

#include "lista.h"

void inicializar(TLista *l) {
  l->cantidad = 0;
}

int longitud(TLista l) {
  return l.cantidad;
}

int obtener(TLista l, int pos) {
  return l.elementos[pos];
}

TResultado insertar(TLista *l, int pos, int x) {
  if (l->cantidad == MAX) {
    return LISTA_LLENA;
  }
  if (pos < 0 || pos > l->cantidad) {
    return POSICION_INVALIDA;
  }
  for (int i = l->cantidad; i > pos; i--) {
    l->elementos[i] = l->elementos[i - 1];
  }
  l->elementos[pos] = x;
  l->cantidad = l->cantidad + 1;
  return OK;
}

#include <stdio.h>
#include "lista.h"

int main() {
  TLista l;
  int n;
  int x;
  int pos;

  inicializar(&l);
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &x);
    insertar(&l, longitud(l), x);
  }
  scanf("%d", &pos);
  scanf("%d", &x);
  if (insertar(&l, pos, x) == OK) {
    for (int i = 0; i < longitud(l); i++) {
      printf("%d ", obtener(l, i));
    }
  } else {
    printf("No se pudo insertar");
  }
  return 0;
}

